import { useState, useEffect } from "react";
import styled from "styled-components";
import { Table } from "antd";
import type { ColumnsType } from "antd/es/table";
import { useTranslation } from "react-i18next";

interface TableDataType {
  key: React.Key;
  argument: string;
  describe: string;
  type: string;
  default: string;
  notes: string;
}

interface ArguData {
  arguName: string;
  fields: TableDataType[];
}

interface ComponentProps {
  id: string;
  name: string;
  methodDescribe: string;
  fields: any[];
  isAlias?: boolean;
}

const Container = styled.div`
  display: flex;
  flex-direction: column;
  gap: 10px;
`;

const Space = styled.div`
  padding: 24px;
`;

const TypeField = (props: ComponentProps) => {
  const { id, methodDescribe, name, fields, isAlias = false } = props;
  const { t } = useTranslation();
  const columns: ColumnsType<TableDataType> = [
    {
      title: t("text_table_header_argument"),
      // dataIndex: "argument",
      dataIndex: "alias",
      width: 200,
    },
    ...(isAlias
      ? [
          {
            title: t("text_table_header_alias"),
            // dataIndex: "alias",
            dataIndex: "argument",
            width: 200,
          },
        ]
      : []),
    {
      title: t("text_table_header_describe"),
      dataIndex: "describe",
    },
    {
      title: t("text_table_header_type"),
      dataIndex: "type",
      width: 200,
    },
    {
      title: t("text_table_header_default"),
      dataIndex: "default",
      width: 200,
    },
    {
      title: t("text_table_header_notes"),
      dataIndex: "notes",
      width: 150,
    },
  ];

  useEffect(() => {}, []);

  return (
    <>
      <div>
        <Space id={id} />

        <Container>
          <h2>{name}</h2>
          <p>{methodDescribe}</p>
          <Table
            columns={columns}
            dataSource={fields}
            pagination={false}
            bordered
          />
        </Container>
      </div>
    </>
  );
};

export default TypeField;
