import React, { useEffect } from "react";
import useGetDocList from "@/hooks/useGetDocList";
import { useLocation, useNavigate } from "react-router-dom";
import styled from "styled-components";
import { Divider } from "antd";

import APIField from "./components/APIField";
import TypeField from "./components/TypeField";
import CodeField from "./components/CodeField";

const ContentContainer = styled.div`
  display: flex;
  flex-direction: column;
  padding: 48px;
  width: 100%;
  background-color: white;
  gap: 40px;
  overflow: auto;
`;

const Space = styled.div`
  padding: 36px;
`;

const Doc: React.FC = () => {
  const location = useLocation();
  const { hash } = location;
  const { apiList = [], typeList = [], codeList = [] } = useGetDocList();

  useEffect(() => {
    const queryParams = new URLSearchParams(location.search);
    const section = queryParams.get("section");
    if (section) {
      const element = document.getElementById(section);
      if (element) {
        element.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    }
  }, [hash]);

  return (
    <>
      <ContentContainer>
        <h1>API</h1>
        {apiList.map((apiData): any => {
          const {
            id = "",
            fullMethod,
            methodDescribe,
            version,
            propertyList,
            returnValue,
          } = apiData;
          return (
            <APIField
              id={id}
              fullMethod={fullMethod}
              methodDescribe={methodDescribe}
              version={version}
              propertyList={propertyList}
              returnValue={returnValue}
            ></APIField>
          );
        })}

        <div>
          <Divider />
          <h1>Porperty Type</h1>
        </div>
        {typeList.map((type): any => {
          const { id = "", name, methodDescribe, fields, isAlias } = type;
          return (
            <TypeField
              id={id}
              name={name}
              methodDescribe={methodDescribe}
              fields={fields}
              isAlias={isAlias}
            ></TypeField>
          );
        })}

        <div>
          <Divider />
          <h1>Code</h1>
        </div>
        {codeList.map((type): any => {
          const { id = "", name, methodDescribe, fields } = type;
          return (
            <CodeField
              id={id}
              name={name}
              methodDescribe={methodDescribe}
              fields={fields}
            ></CodeField>
          );
        })}
        <Space />
      </ContentContainer>
    </>
  );
};

export default Doc;
