import { useState, useEffect } from "react";
import styled from "styled-components";
import { Table } from "antd";
import type { ColumnsType } from "antd/es/table";
import { useTranslation } from "react-i18next";

interface TableDataType {
  key: React.Key;
  argument: string;
  describe: string;
  type: string;
  default: string;
}

interface ArguData {
  arguName: string;
  fields: TableDataType[];
}

interface ComponentProps {
  id: string;
  name: string;
  methodDescribe: string;
  fields: any[];
}

const Container = styled.div`
  display: flex;
  flex-direction: column;
  gap: 10px;
`;

const Space = styled.div`
  padding: 24px;
`;

const CodeField = (props: ComponentProps) => {
  const { id, methodDescribe, name, fields } = props;
  const { t } = useTranslation();
  const columns: ColumnsType<TableDataType> = [
    {
      title: t("text_table_header_code"),
      dataIndex: "code",
      width: 100,
    },
    // {
    //   title: t("text_table_header_message"),
    //   dataIndex: "message",
    //   width: 200,
    // },
    {
      title: t("text_table_header_describe"),
      dataIndex: "describe",
    },
  ];
  useEffect(() => {}, []);

  return (
    <>
      <div>
        <Space id={id} />

        <Container>
          <h2>{name}</h2>
          <p>{methodDescribe}</p>
          <Table
            columns={columns}
            dataSource={fields}
            pagination={false}
            bordered
          />
        </Container>
      </div>
    </>
  );
};

export default CodeField;
