import { useState, useEffect } from "react";
import styled from "styled-components";
import { Layout, Popover, Dropdown, Select } from "antd";
import { GlobalOutlined } from "@ant-design/icons";
import logo from "@/assets/image/logo.png";
import type { MenuProps } from "antd";
import { useTranslation } from "react-i18next";
import { useLocation, useNavigate } from "react-router-dom";

const { Header, Content, Footer, Sider } = Layout;

const MyHeader = styled(Header)`
  height: 48px !important;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 28px 0 14px;
  > div {
    display: flex;
    align-items: center;
  }
  position: relative;
  width: 100%;
  top: 0;
  z-index: 1000;
`;
const HeaderTitle = styled.div`
  color: white;
`;
const MenuItem = styled.p`
  color: blue;
  cursor: pointer;
`;
const ImgWrapper = styled.img`
  width: 152px;
  height: 32px;
  object-fit: contain;
`;
const HeaderEnd = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  color: white;
`;

const MenuContainer = styled.div`
  display: flex;
  gap: 15px;
`;

export default function LayoutHeader() {
  const { LIB_DOC_GLOBAL } = window as any;
  const { versionList } = LIB_DOC_GLOBAL;

  const [versionOpts, setVersionOpts] = useState([]);
  const [versionVal, setVersionVal] = useState("");
  const location = useLocation();
  const navigate = useNavigate();
  const { t, i18n } = useTranslation();
  const items: MenuProps["items"] = [
    {
      label: t("zh_tw"),
      key: "zh_tw",
    },
    {
      label: t("en_us"),
      key: "en_us",
    },
    {
      label: t("zh_cn"),
      key: "zh_cn",
    },
  ];

  // util: find parent paths (ex: "/a/b/c/" => "/a/b/" )
  const getGrandparentPath = (pathname: string): string => {
    const currentPath = pathname;
    const pathParts = currentPath.split("/");
    // adjust path if it is file protocal
    if (window.location.protocol === "file:") {
      pathParts.splice(pathParts.length - 2, 2);
      pathParts.push("");
    } else {
      pathParts.splice(pathParts.length - 2, 1);
    }
    return pathParts.join("/");
  };

  // util: get parent path name (ex: "/a/b/c/" => "c" )
  const getParentPathname = (pathname: string): string => {
    const currentPath = pathname;
    const pathParts = currentPath.split("/");
    return pathParts[pathParts.length - 2];
  };

  // action: href to other version
  const handleVersionChange = (value: string, option: any) => {
    setVersionVal(value);
    const grandparent = getGrandparentPath(window.location.pathname);

    // add "index.html" if it is file protocal
    const htmlFile = window.location.protocol === "file:" ? "index.html" : "";
    window.location.href = `${grandparent}${value}/${htmlFile}${window.location.hash}`;
  };

  // action: click on i18n lang
  const onClick: MenuProps["onClick"] = ({ key }) => {
    const searchParams = new URLSearchParams(location.search);
    searchParams.set("lang", key);
    navigate(`${location.pathname}?${searchParams.toString()}`);
    i18n.changeLanguage(key);
  };

  // pull version list
  useEffect(() => {
    const getVersionData = async () => {
      const optData = versionList.map((ver: string) => {
        return { label: ver, value: ver };
      });
      setVersionOpts(optData);
    };
    getVersionData();
  }, []);

  // init version select value
  useEffect(() => {
    const version = getParentPathname(window.location.pathname);
    setVersionVal(version);
  }, []);

  return (
    <MyHeader>
      <HeaderTitle>
        {/* <ImgWrapper src={logo} alt="" /> */}
        WebFXScan JS Library
      </HeaderTitle>
      <MenuContainer>
        <Select
          style={{ width: 200 }}
          showSearch
          placeholder="Version"
          optionFilterProp="children"
          onChange={handleVersionChange}
          options={versionOpts}
          value={versionVal}
        />
        <Dropdown
          placement="bottom"
          menu={{ items, onClick }}
          trigger={["click"]}
        >
          <HeaderEnd>
            <GlobalOutlined style={{ fontSize: "24px" }} />
          </HeaderEnd>
        </Dropdown>
      </MenuContainer>
    </MyHeader>
  );
}
